<?php

namespace App\Core;

/**
 * Encryption — authenticated symmetric encryption using libsodium (built into PHP 7.2+).
 *
 * Algorithm: XSalsa20-Poly1305 (secretbox)
 *   - 256-bit key
 *   - 192-bit random nonce per encryption
 *   - Authenticated: tampering is detected and throws
 *
 * Output format stored in DB: base64( nonce [24 bytes] + ciphertext )
 *
 * Key source: APP_KEY in .env — must be exactly 32 bytes of random data,
 * stored as base64 (e.g. generated by: php -r "echo base64_encode(random_bytes(32));")
 *
 * Generating a key:
 *   php -r "echo base64_encode(random_bytes(32)) . PHP_EOL;"
 *   → paste result as APP_KEY=<output> in .env
 */
class Encryption
{
    private static ?string $key = null;

    // ── Public API ──────────────────────────────────────────────

    /**
     * Encrypt a string. Returns a base64-encoded string safe to store in any text column.
     * Returns '' if input is ''.
     */
    public static function encrypt(string $plaintext): string
    {
        if ($plaintext === '') return '';

        $key   = self::key();
        $nonce = random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES); // 24 bytes
        $cipher = sodium_crypto_secretbox($plaintext, $nonce, $key);

        sodium_memzero($plaintext);

        return base64_encode($nonce . $cipher);
    }

    /**
     * Decrypt a value produced by encrypt(). Returns '' if input is ''.
     * Throws \RuntimeException if the ciphertext is invalid or tampered.
     */
    public static function decrypt(string $ciphertext): string
    {
        if ($ciphertext === '') return '';

        // Not encrypted yet (e.g. legacy plaintext rows during migration)
        if (!self::looksEncrypted($ciphertext)) return $ciphertext;

        $key  = self::key();
        $raw  = base64_decode($ciphertext, strict: true);

        if ($raw === false || strlen($raw) < SODIUM_CRYPTO_SECRETBOX_NONCEBYTES) {
            throw new \RuntimeException('Encryption: invalid ciphertext (too short or bad base64).');
        }

        $nonce      = substr($raw, 0, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
        $encrypted  = substr($raw, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
        $plaintext  = sodium_crypto_secretbox_open($encrypted, $nonce, $key);

        if ($plaintext === false) {
            throw new \RuntimeException('Encryption: decryption failed — data may be tampered or key is wrong.');
        }

        return $plaintext;
    }

    /**
     * Encrypt an array of fields from a row.
     * Only encrypts fields listed in $fields; everything else is passed through.
     */
    public static function encryptFields(array $row, array $fields): array
    {
        foreach ($fields as $f) {
            if (isset($row[$f]) && $row[$f] !== '') {
                $row[$f] = self::encrypt((string) $row[$f]);
            }
        }
        return $row;
    }

    /**
     * Decrypt an array of fields from a row.
     */
    public static function decryptFields(array $row, array $fields): array
    {
        foreach ($fields as $f) {
            if (isset($row[$f]) && $row[$f] !== '') {
                $row[$f] = self::decrypt((string) $row[$f]);
            }
        }
        return $row;
    }

    // ── Key management ──────────────────────────────────────────

    private static function key(): string
    {
        if (self::$key !== null) return self::$key;

        $b64 = Env::get('APP_KEY', '');
        if ($b64 === '') {
            throw new \RuntimeException(
                'APP_KEY is not set in .env. ' .
                'Generate one with: php -r "echo base64_encode(random_bytes(32)) . PHP_EOL;"'
            );
        }

        $key = base64_decode($b64, strict: true);
        if ($key === false || strlen($key) !== SODIUM_CRYPTO_SECRETBOX_KEYBYTES) {
            throw new \RuntimeException(
                'APP_KEY must be a base64-encoded 32-byte key. ' .
                'Generate one with: php -r "echo base64_encode(random_bytes(32)) . PHP_EOL;"'
            );
        }

        return self::$key = $key;
    }

    /**
     * Heuristic: our ciphertext is always valid base64 with length >= 33 bytes decoded.
     * Used to safely handle any legacy plaintext rows during migration.
     */
    private static function looksEncrypted(string $value): bool
    {
        if (strlen($value) < 44) return false; // 24-byte nonce + at least 1 byte cipher, base64'd ≥ 34 chars
        $decoded = base64_decode($value, strict: true);
        return $decoded !== false && strlen($decoded) >= SODIUM_CRYPTO_SECRETBOX_NONCEBYTES + 1;
    }

    // ── Utility ─────────────────────────────────────────────────

    /** Generate a fresh APP_KEY and return it as base64. Use once during setup. */
    public static function generateKey(): string
    {
        return base64_encode(random_bytes(SODIUM_CRYPTO_SECRETBOX_KEYBYTES));
    }

    /** True when sodium is available (it always is in PHP 7.2+). */
    public static function available(): bool
    {
        return function_exists('sodium_crypto_secretbox');
    }
}
